// D1 schema. Column names are snake_case and match the record schemas in
// `@habits/contracts`, so a row minus `user_id` is the contract record (see
// `records.ts`). Instants are integer UTC ms read as `number`; calendar dates
// are `YYYY-MM-DD` text. Every domain row belongs to a Better Auth `user`
// (`ON DELETE CASCADE`), and every query is still scoped by `user_id`.
//
// The auth tables live in `auth-schema.ts`, generated by the Better Auth CLI
// (`pnpm --filter api auth:generate`): regenerate it instead of editing it.
// Unlike the domain tables, its instants are `timestamp_ms` (read as `Date`)
// because Better Auth owns those rows.
import { DEFAULT_TIME_ZONE, type StoredSchedule } from "@habits/contracts";
import { type SQL, sql } from "drizzle-orm";
import {
	type AnySQLiteColumn,
	check,
	index,
	integer,
	primaryKey,
	sqliteTable,
	text,
	uniqueIndex,
} from "drizzle-orm/sqlite-core";
import { user } from "./auth-schema.ts";

export * from "./auth-schema.ts";

/** Integer UTC milliseconds, read as `number` (not `Date`). */
const timestampMs = () => integer({ mode: "number" });

/** Record id: UUID (v7 when client-generated), stored as text. */
const id = () => text().primaryKey();

/** Owner of the row; deleting the user deletes their data. */
const userId = () =>
	text()
		.notNull()
		.references(() => user.id, { onDelete: "cascade" });

const timestamps = {
	created_at: timestampMs().notNull(),
	updated_at: timestampMs().notNull(),
};

/**
 * Position of the row's last write in the user's change feed (the sync
 * cursor). Never written by the app: SQLite triggers (migration `0004_sync`)
 * set it from `sync_state.seq` after every insert or update, so every write
 * path gets a unique, increasing value. Not part of the contract records.
 */
const serverSeq = () => integer().notNull().default(0);

/** Valid `YYYY-MM-DD` dates are the ones SQLite's `date()` returns unchanged. */
const isCalendarDate = (column: AnySQLiteColumn): SQL =>
	sql`date(${column}) IS ${column}`;

export const habits = sqliteTable(
	"habits",
	{
		id: id(),
		user_id: userId(),
		name: text().notNull(),
		/**
		 * Optional notes (2.12.0): plain text with a little Markdown, empty when
		 * none. Not in the `server_seq` update trigger's column list: every
		 * write of it also sets `updated_at` (`changedHabitFields`).
		 */
		description: text().notNull().default(""),
		/**
		 * Discriminated union validated with `Schedule` from contracts on every
		 * write. The CHECK only guarantees JSON with a string `type`, so new
		 * schedule types need no migration.
		 */
		schedule: text({ mode: "json" }).$type<StoredSchedule>().notNull(),
		start_date: text().notNull(),
		archived_at: timestampMs(),
		/**
		 * Position in the user's list (2.4.0): a fractional index compared as
		 * text (core `sort-key.ts`). Empty sorts last; migration 0006 filled
		 * the existing habits in creation order.
		 */
		sort_key: text().notNull().default(""),
		...timestamps,
		deleted_at: timestampMs(),
		server_seq: serverSeq(),
	},
	(t) => [
		index("habits_user_updated_idx").on(t.user_id, t.updated_at),
		index("habits_user_seq_idx").on(t.user_id, t.server_seq),
		check("habits_start_date_check", isCalendarDate(t.start_date)),
		check(
			"habits_schedule_check",
			sql`json_valid(${t.schedule}) AND json_type(${t.schedule}, '$.type') IS 'text'`
		),
	]
);

/** A row means "done"; un-checking sets `deleted_at` so the change syncs. */
export const completions = sqliteTable(
	"completions",
	{
		id: id(),
		user_id: userId(),
		habit_id: text()
			.notNull()
			.references(() => habits.id),
		date: text().notNull(),
		completed_at: timestampMs().notNull(),
		...timestamps,
		deleted_at: timestampMs(),
		server_seq: serverSeq(),
	},
	(t) => [
		uniqueIndex("completions_habit_date_unique").on(t.habit_id, t.date),
		index("completions_user_date_idx").on(t.user_id, t.date),
		index("completions_user_updated_idx").on(t.user_id, t.updated_at),
		index("completions_user_seq_idx").on(t.user_id, t.server_seq),
		check("completions_date_check", isCalendarDate(t.date)),
	]
);

export const userSettings = sqliteTable(
	"user_settings",
	{
		user_id: text()
			.primaryKey()
			.references(() => user.id, { onDelete: "cascade" }),
		timezone: text().notNull().default(DEFAULT_TIME_ZONE),
		/**
		 * `HH:MM` in `timezone`, in 15-minute steps since 2.2.0 (contracts; the
		 * CHECK below predates the steps and is kept to avoid a table rebuild);
		 * null turns reminders off.
		 */
		reminder_time: text(),
		/** Morning digest at the fixed `MORNING_DIGEST_TIME` (core). */
		morning_digest_enabled: integer({ mode: "boolean" })
			.notNull()
			.default(true),
		/** Habit names in notification texts. */
		show_titles_in_notifications: integer({ mode: "boolean" })
			.notNull()
			.default(true),
		...timestamps,
	},
	(t) => [
		check(
			"user_settings_reminder_time_check",
			sql`${t.reminder_time} IS NULL OR (${t.reminder_time} GLOB '[0-2][0-9]:[0-5][0-9]' AND ${t.reminder_time} < '24:00')`
		),
	]
);

/**
 * Flat storage for the `PushSubscription` union: `webpush` rows use
 * endpoint/p256dh/auth, `expo` rows use token. Not syncable, so removal is a
 * hard delete (e.g. after a 404/410 from the push service).
 */
export const pushSubscriptions = sqliteTable(
	"push_subscriptions",
	{
		id: id(),
		user_id: userId(),
		kind: text({ enum: ["webpush", "expo"] }).notNull(),
		endpoint: text(),
		p256dh: text(),
		auth: text(),
		token: text(),
		device_label: text(),
		last_seen_at: timestampMs().notNull(),
		...timestamps,
	},
	(t) => [
		uniqueIndex("push_subscriptions_endpoint_unique").on(t.endpoint),
		uniqueIndex("push_subscriptions_token_unique").on(t.token),
		index("push_subscriptions_user_idx").on(t.user_id),
		check(
			"push_subscriptions_kind_check",
			sql`(${t.kind} = 'webpush' AND ${t.endpoint} IS NOT NULL AND ${t.p256dh} IS NOT NULL AND ${t.auth} IS NOT NULL AND ${t.token} IS NULL) OR (${t.kind} = 'expo' AND ${t.token} IS NOT NULL AND ${t.endpoint} IS NULL AND ${t.p256dh} IS NULL AND ${t.auth} IS NULL)`
		),
	]
);

export type HabitRow = typeof habits.$inferSelect;
export type CompletionRow = typeof completions.$inferSelect;
export type UserSettingsRow = typeof userSettings.$inferSelect;
export type PushSubscriptionRow = typeof pushSubscriptions.$inferSelect;

/**
 * Server-only reminder bookkeeping (not a contract record, not synced). Kept
 * out of `user_settings` so its row stays exactly the `UserSettings` record.
 */
export const reminderState = sqliteTable(
	"reminder_state",
	{
		user_id: text()
			.primaryKey()
			.references(() => user.id, { onDelete: "cascade" }),
		/**
		 * Local date (user's time zone) of the last reminder claimed by the cron.
		 * Set with a conditional update BEFORE sending: at most one per day.
		 */
		last_reminder_date: text(),
		/** Same as `last_reminder_date`, for the morning digest (independent). */
		last_digest_date: text(),
		/** Last `POST /v1/push/test` (rate limit). */
		last_test_push_at: timestampMs(),
		updated_at: timestampMs().notNull(),
	},
	(t) => [
		check(
			"reminder_state_last_reminder_date_check",
			sql`${t.last_reminder_date} IS NULL OR date(${t.last_reminder_date}) IS ${t.last_reminder_date}`
		),
		check(
			"reminder_state_last_digest_date_check",
			sql`${t.last_digest_date} IS NULL OR date(${t.last_digest_date}) IS ${t.last_digest_date}`
		),
	]
);

/**
 * Expo push tickets waiting for their receipt (checked by the next cron runs,
 * dropped after 24 h). Removing the device removes its tickets.
 */
export const pushTickets = sqliteTable(
	"push_tickets",
	{
		/** Expo receipt id. */
		id: text().primaryKey(),
		user_id: userId(),
		subscription_id: text()
			.notNull()
			.references(() => pushSubscriptions.id, { onDelete: "cascade" }),
		created_at: timestampMs().notNull(),
	},
	(t) => [index("push_tickets_created_idx").on(t.created_at)]
);

export type ReminderStateRow = typeof reminderState.$inferSelect;
export type PushTicketRow = typeof pushTickets.$inferSelect;

/**
 * Server-only sync bookkeeping, one row per user (created by the triggers on
 * the user's first write).
 */
export const syncState = sqliteTable("sync_state", {
	user_id: text()
		.primaryKey()
		.references(() => user.id, { onDelete: "cascade" }),
	/** Last `server_seq` given to one of the user's rows. */
	seq: integer().notNull().default(0),
	/**
	 * Highest `server_seq` among purged tombstones: a pull cursor below it may
	 * have missed a deletion, so it must start over (`reset`).
	 */
	purged_seq: integer().notNull().default(0),
});

/**
 * Applied sync mutations, for idempotency by `mutation_id` (kept for
 * `PROCESSED_MUTATION_RETENTION_DAYS`). Rejected mutations are not recorded,
 * so a retry is evaluated again.
 */
export const processedMutations = sqliteTable(
	"processed_mutations",
	{
		user_id: userId(),
		mutation_id: text().notNull(),
		/** Id of the record the mutation touched, as stored. */
		canonical_id: text().notNull(),
		processed_at: timestampMs().notNull(),
	},
	(t) => [
		primaryKey({ columns: [t.user_id, t.mutation_id] }),
		index("processed_mutations_processed_idx").on(t.processed_at),
	]
);

export type SyncStateRow = typeof syncState.$inferSelect;
